# --------------------------------------------------------------------------- #
# 数据结构
# --------------------------------------------------------------------------- #


@dataclass
class FileRecord:
    """单个被统计文件的构成信息 (行级来源拆分)."""

    rel_path: str
    module: str
    language: str
    total_lines: int
    code_lines: int
    human_lines: int
    mixed_lines: int
    ai_lines: int

    @property
    def source(self) -> str:
        """文件级分类: 纯人工 / 纯 AI / 混合."""
        if self.mixed_lines > 0:
            return SOURCE_PARTIAL
        if self.human_lines > 0 and self.ai_lines > 0:
            return SOURCE_PARTIAL
        if self.ai_lines > 0:
            return SOURCE_AI
        return SOURCE_HUMAN


@dataclass
class Aggregate:
    """按某一维度聚合出的计数."""

    files: int = 0
    code_lines: int = 0
    human_lines: int = 0
    mixed_lines: int = 0
    ai_lines: int = 0

    def add(self, rec: FileRecord) -> None:
        self.files += 1
        self.code_lines += rec.code_lines
        self.human_lines += rec.human_lines
        self.mixed_lines += rec.mixed_lines
        self.ai_lines += rec.ai_lines


@dataclass
class CountPair:
    """同一标签下按两种口径的计数."""

    files: int = 0
    lines: int = 0

    def add_file(self, lines: int) -> None:
        self.files += 1
        self.lines += lines

    def add_lines(self, lines: int) -> None:
        self.lines += lines

    def to_payload(self) -> Dict[str, int]:
        return {"files": self.files, "lines": self.lines}


@dataclass
class ModuleSlice:
    """单个模块的语言 / 来源切片."""

    module: str
    languages: Dict[str, CountPair]
    sources: Dict[str, CountPair]
    files: int = 0
    lines: int = 0

    def to_payload(self) -> Dict[str, object]:
        return {
            "module": self.module,
            "files": self.files,
            "lines": self.lines,
            "languages": {
                name: pair.to_payload() for name, pair in self.languages.items()
            },
            "sources": {name: pair.to_payload() for name, pair in self.sources.items()},
        }


@dataclass
class CompositionReport:
    """整份构成画像."""

    root: str
    records: List[FileRecord]

    @property
    def total_files(self) -> int:
        return len(self.records)

    @property
    def total_code_lines(self) -> int:
        return sum(r.code_lines for r in self.records)

    def by_language(self) -> List[Tuple[str, Aggregate]]:
        buckets: Dict[str, Aggregate] = {}
        for rec in self.records:
            buckets.setdefault(rec.language, Aggregate()).add(rec)
        return sorted(buckets.items(), key=lambda kv: kv[1].code_lines, reverse=True)

    def by_source_lines(self) -> Dict[str, int]:
        return {
            SOURCE_HUMAN: sum(r.human_lines for r in self.records),
            SOURCE_PARTIAL: sum(r.mixed_lines for r in self.records),
            SOURCE_AI: sum(r.ai_lines for r in self.records),
        }

    def by_source_files(self) -> Dict[str, int]:
        out = {name: 0 for name in SOURCE_ORDER}
        for rec in self.records:
            out[rec.source] += 1
        return out

    def by_module(self) -> List[Tuple[str, Aggregate]]:
        buckets: Dict[str, Aggregate] = {}
        for rec in self.records:
            buckets.setdefault(rec.module, Aggregate()).add(rec)
        return sorted(buckets.items(), key=lambda kv: kv[1].code_lines, reverse=True)

    def module_slice(self) -> List[ModuleSlice]:
        """每个模块的 (语言, 来源) 双口径切片, 供前端画饼."""
        rows: Dict[str, ModuleSlice] = {}
        for rec in self.records:
            row = rows.get(rec.module)
            if row is None:
                row = ModuleSlice(
                    module=rec.module,
                    languages={lang: CountPair() for lang in LANGUAGE_ORDER},
                    sources={name: CountPair() for name in SOURCE_ORDER},
                )
                rows[rec.module] = row

            row.files += 1
            row.lines += rec.code_lines

            lang_slot = row.languages.setdefault(rec.language, CountPair())
            lang_slot.add_file(rec.code_lines)

            # 行级: 人工/混合/AI 按行拆进对应槽; 文件级: 整文件归入文件分类.
            for name, inc in (
                (SOURCE_HUMAN, rec.human_lines),
                (SOURCE_PARTIAL, rec.mixed_lines),
                (SOURCE_AI, rec.ai_lines),
            ):
                slot = row.sources.setdefault(name, CountPair())
                slot.add_lines(inc)
            row.sources[rec.source].files += 1

        return sorted(rows.values(), key=lambda r: r.lines, reverse=True)


# --------------------------------------------------------------------------- #
# 扫描与分类
# --------------------------------------------------------------------------- #


def should_skip_dir(name: str) -> bool:
    return name in EXCLUDE_DIRS


def module_of(rel_path: str) -> str:
    normalized = rel_path.replace("\\", "/")
    best: Optional[Tuple[str, str]] = None
    for prefix, label in MODULE_GROUPS:
        if normalized == prefix or normalized.startswith(prefix + "/"):
            if best is None or len(prefix) > len(best[0]):
                best = (prefix, label)
    return best[1] if best else MODULE_OTHER


def language_of(path: Path) -> Optional[str]:
    ext = path.suffix.lower()
    return EXT_TO_LANGUAGE.get(ext)


def count_lines(text: str) -> Tuple[int, int]:
    lines = text.splitlines()
    code_lines = sum(1 for line in lines if line.strip())
    return len(lines), code_lines


def find_block_end(lines: List[str], start: int) -> int:
    depth = 0
    seen_open = False
    for i in range(start, len(lines)):
        depth += lines[i].count("{")
        depth -= lines[i].count("}")
        if lines[i].count("{") > 0:
            seen_open = True
        if seen_open and depth <= 0:
            return i
    return len(lines) - 1


def find_enclosing_mod_start(lines: List[str], marker_idx: int) -> int:
    for i in range(marker_idx, -1, -1):
        if MOD_START_RE.search(lines[i]):
            return i
    return marker_idx


def attribute_lines(text: str) -> List[str]:
    """按 AI 标识为每一行分配 human / mixed / ai."""
    lines = text.splitlines()
    if not lines:
        return []

    module_marks: List[Tuple[int, bool]] = []

    for i, line in enumerate(lines):
        if MODULE_PARTIAL_RE.search(line):
            module_marks.append((i, True))
            continue
        if MODULE_FULL_RE.search(line):
            module_marks.append((i, False))
            continue
        if i >= FILE_MARKER_SCAN_LINES:
            continue
        if FILE_FULL_RE.search(line):
            return [LINE_AI] * len(lines)
        if re.search(r"partially generated by AI", line, re.I):
            return [LINE_MIXED] * len(lines)

    attr = [LINE_HUMAN] * len(lines)
    for marker_idx, is_partial in module_marks:
        start = find_enclosing_mod_start(lines, marker_idx)
        end = find_block_end(lines, start)
        tag = LINE_MIXED if is_partial else LINE_AI
        for j in range(start, end + 1):
            attr[j] = tag
    return attr


def scan_file(root: Path, path: Path) -> Optional[FileRecord]:
    language = language_of(path)
    if language is None:
        return None

    try:
        text = path.read_text(encoding="utf-8")
    except UnicodeDecodeError:
        return None
    except OSError as e:
        print(f"  ⚠️  无法读取 {path}: {e}")
        return None

    total_lines, code_lines = count_lines(text)
    if code_lines == 0:
        return None

    lines = text.splitlines()
    attr = attribute_lines(text)
    if len(attr) < len(lines):
        attr = attr + [LINE_HUMAN] * (len(lines) - len(attr))

    human = mixed = ai = 0
    for line, tag in zip(lines, attr):
        if not line.strip():
            continue
        if tag == LINE_AI:
            ai += 1
        elif tag == LINE_MIXED:
            mixed += 1
        else:
            human += 1

    rel_path = path.relative_to(root).as_posix()
    return FileRecord(
        rel_path=rel_path,
        module=module_of(rel_path),
        language=language,
        total_lines=total_lines,
        code_lines=code_lines,
        human_lines=human,
        mixed_lines=mixed,
        ai_lines=ai,
    )


def collect_files(root: Path) -> List[FileRecord]:
    print(f"📂 扫描仓库: {root}")
    records: List[FileRecord] = []
    for dirpath, dirnames, filenames in os.walk(root):
        dirnames[:] = sorted(d for d in dirnames if not should_skip_dir(d))
        current = Path(dirpath)
        for name in sorted(filenames):
            if name in EXCLUDE_FILES:
                continue
            rec = scan_file(root, current / name)
            if rec is not None:
                records.append(rec)
    print(f"  ✅ 收录 {len(records)} 个文件.")
    return records


# --------------------------------------------------------------------------- #
# HTML 渲染
# --------------------------------------------------------------------------- #


def fmt_int(n: int) -> str:
    return f"{n:,}"


def html_escape(text: str) -> str:
    return (
        text.replace("&", "&amp;")
        .replace("<", "&lt;")
        .replace(">", "&gt;")
        .replace('"', "&quot;")
    )


def build_payload(report: CompositionReport) -> Dict[str, object]:
    """前端画饼用的数据包 (两种口径都带上, 由按钮切换)."""
    lang_items = report.by_language()
    modules = report.module_slice()

    overview_lang = {
        name: {"files": agg.files, "lines": agg.code_lines} for name, agg in lang_items
    }
    source_lines = report.by_source_lines()
    source_files = report.by_source_files()
    overview_src = {
        name: {"files": source_files[name], "lines": source_lines[name]}
        for name in SOURCE_ORDER
    }

    return {
        "root": report.root,
        "totals": {
            "files": report.total_files,
            "lines": report.total_code_lines,
        },
        "languageOrder": list(LANGUAGE_ORDER),
        "languageColors": LANGUAGE_COLORS,
        "sourceOrder": list(SOURCE_ORDER),
        "sourceColors": SOURCE_COLORS,
        "overview": {
            "languages": overview_lang,
            "sources": overview_src,
        },
        "modules": [mod.to_payload() for mod in modules],
    }


def render_html(report: CompositionReport) -> str:
    payload = build_payload(report)
    payload_json = json.dumps(payload, ensure_ascii=False)
    return HTML_TEMPLATE.replace("__PAYLOAD_JSON__", payload_json)


